from pathlib import Path
import pandas as pd
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import letter
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
pdfmetrics.registerFont(TTFont("DejaVuSans","/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))
pdfmetrics.registerFont(TTFont("DejaVuSans-Bold","/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"))
pdfmetrics.registerFontFamily("DejaVuSans",normal="DejaVuSans",bold="DejaVuSans-Bold",italic="DejaVuSans",boldItalic="DejaVuSans-Bold")
r=Path(__file__).resolve().parent.parent;styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Body',fontName='DejaVuSans',fontSize=11,leading=15,spaceAfter=9,textColor=colors.HexColor('#102238')))
styles['Title'].fontName='DejaVuSans-Bold'
styles['Heading2'].fontName='DejaVuSans-Bold'
styles['Heading2'].keepWithNext=True
flow=[]
def p(t):flow.append(Paragraph(t,styles['Body']))
def h(t):flow.append(Paragraph(t,styles['Heading2']))
flow.append(Paragraph('Story 3: Methods and visual choices',styles['Title']));p('Muhammad Suffyan Khan · DATA 608 · Fall 2026')
h('Question, audience and scope');p('Do stricter gun laws help reduce firearm mortality? This story helps students and policy readers compare 50 states in 2024. It identifies the state-level association and visible exceptions. It does not estimate the effect of passing a particular law.')
h('API retrieval and outcome');p('The code queries the CDC NCHS open-data API at https://data.cdc.gov/resource/489q-934x.json. It filters for 2024 Q4, 12 months ending with quarter, Firearm-related injury, and Age-adjusted. One successful response contains all 50 state rates. The archived request URL, retrieval time, response and metadata are in data/raw/. Rates are deaths per 100,000 and include suicides, homicides and other firearm injury deaths. The API dataset is designated provisional and may be revised. This annual period is distinct from the three-month annualized series.')
h('Five-point law scale');p('GIFFORDS 2024 grades supply a reproducible ordering of state law strength. The first letter defines the five bins: F = 1 (most lax), D = 2 (lax), C = 3 (middle), B = 4 (strict), and A = 5 (strictest). Plus and minus variants remain in the saved grade field. This is an ordinal Likert-style classification for the assignment, rather than an opinion survey. Unequal bin sizes are retained. GIFFORDS is an advocacy organization and the index reflects its policy choices. Its published death-rate column is excluded from this analysis.')
h('Why these heat maps');p('The law and mortality maps use the same labeled state tile layout. Equal tile sizes keep small states visible; the schematic positions do not depict physical area or precise adjacency. The law map uses five ordered colors and the mortality map uses a fixed 0-to-30 sequential scale with printed values. Both use Viridis colors. The mortality-band heat map uses sequential blues to encode within-group percentages on a fixed 0-to-100 scale. Every cell prints both the state count and percentage, with the group size beside the row. Black outlines and connected annotations emphasize 15 of 22 F-grade states (68%) at rates of 16 or more and 7 of 13 A-grade states (54%) below 8. Numbered outlines on the mortality map locate the extremes and New Mexico exception. Printed law levels support the law-map color scale. These on-chart cues strengthen saliency, while geographic and category-based heat maps offer variety without adding chart types outside the assignment. Rounded percentages may not sum to 100%. Separate legends prevent viewers from treating law levels and deaths as the same numerical quantity.')
h('Analysis and limits');p('The A-grade group averages 8.4 deaths per 100,000 versus 18.6 among F-grade states. Spearman correlation between ordinal law level and mortality is -0.717. New Mexico (B-, 26.6) is an exception. Category means treat each state equally and do not equal a pooled national rate. The B-group mean exceeds the C-group mean, so the relationship is not a uniform gradient. Law timing, ownership, economic conditions, demographics, geography, enforcement and neighboring laws remain uncontrolled. The 2024 scorecard and mortality are contemporaneous. A causal study needs policy implementation dates, multiple years and suitable comparison groups.')
p('<b>Conclusion:</b> states with stronger 2024 law grades tended to have lower firearm mortality in 2024. The evidence supports an inverse association while leaving causation unresolved.')
h('Sources and software');p('CDC NCHS API: https://data.cdc.gov/resource/489q-934x.json<br/>CDC definitions: https://www.cdc.gov/nchs/state-stats/deaths/firearms.html<br/>GIFFORDS 2024 scorecard: https://giffords.org/resources/scorecard2024/<br/>Retrieved September 27, 2026. R generated the heat maps, replacing the Python chart applications in Stories 1 and 2. Python handles source retrieval and tables. See the notebook and sources/SOURCES.md for complete checks.')
flow.append(PageBreak());flow.append(Paragraph('All 50 state assignments and rates',styles['Title']));p('GIFFORDS 2024 source grade, derived law level, and 2024 CDC annual age-adjusted firearm mortality per 100,000.')
d=pd.read_csv(r/'data/processed/state_analysis_2024.csv').sort_values('state')
rows=[['State','Source grade','Law level','Deaths / 100,000']]+[[x.state,x.gun_law_grade,str(x.law_level),f'{x.firearm_death_rate_2024:.1f}'] for x in d.itertuples()]
t=Table(rows,colWidths=[190,100,85,135],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#102238')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,-1),'DejaVuSans'),('FONTNAME',(0,0),(-1,0),'DejaVuSans-Bold'),('FONTSIZE',(0,0),(-1,-1),10),('LEADING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('LINEBELOW',(0,0),(-1,-1),.25,colors.HexColor('#CDD6DE'))]));flow.append(t)
SimpleDocTemplate(str(r/'submission/Story3_Methods_and_Visual_Choices.pdf'),pagesize=letter,leftMargin=45,rightMargin=45,topMargin=42,bottomMargin=42,title='Story 3 Methods and Visual Choices',author='Muhammad Suffyan Khan').build(flow)
f=[Paragraph('AI-use disclosure',styles['Title']),Paragraph('ChatGPT assisted with locating and checking public sources, drafting data retrieval and visualization code, preparing the analysis and presentation, and reviewing calculations and layout. The student should personally review and validate the code, values, charts, interpretations, citations and final conclusions before submitting the work under their name.',styles['Body'])]
SimpleDocTemplate(str(r/'submission/AI_USE_DISCLOSURE.pdf'),pagesize=letter,title='Story 3 AI-use disclosure').build(f)
